#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The console-only steps of the BirdJournal accounts backend (issue #60): the budget address, Sign in
# with Apple (App ID, Services ID, key), the Google OAuth client, both stored in AWS Secrets Manager,
# the CDK bootstrap, the deploy, and the `project` cost allocation tag.
#
#   infra/scripts/accounts-wizard.sh              # from the start
#   WIZARD_FROM=11 infra/scripts/accounts-wizard.sh   # resume at stage 11 (e.g. the cost tag, a day later)
#
# Non-secret values are kept in ~/keys/birdjournal.env (never the repo); the Apple key and the Google
# client secret go only to AWS.

run_wizard() {

TOTAL_STAGES=11
WIZARD_FROM="${WIZARD_FROM:-1}"

for tool in aws jq; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required: brew install %s\n' "$tool" "$tool" >&2; exit 1; }
done

INFRA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
mkdir -p "$HOME/keys"
ENV_FILE="$HOME/keys/birdjournal.env"
AWS_REGION="us-west-2" # infra/app.py deploys here
export AWS_PROFILE="${AWS_PROFILE:-lsvr-admin}"
BUNDLE_ID="com.matthewcelia.mybirdjournal"
GOOGLE_SECRET=$(jq -r '.context.googleOAuthSecretName' "$INFRA_DIR/cdk.json")
APPLE_SECRET=$(jq -r '.context.appleSignInSecretName' "$INFRA_DIR/cdk.json")
COGNITO_HOST="$(jq -r '.context.cognitoDomainPrefix' "$INFRA_DIR/cdk.json").auth.$AWS_REGION.amazoncognito.com"
IDP_RESPONSE="https://$COGNITO_HOST/oauth2/idpresponse"
TAGS=(Key=project,Value=birdjournal)

# Fail before the browser work, not after it.
AWS_ACCOUNT=$(aws sts get-caller-identity --query Account --output text 2>/dev/null) || {
  printf 'AWS profile %s has no working credentials (aws sso login --profile %s?). Fix that, then re-run.\n' \
    "$AWS_PROFILE" "$AWS_PROFILE" >&2
  exit 1
}

# begin "Name" starts the next stage, or skips it (returning 1) when it comes before WIZARD_FROM.
begin() {
  if (( _STAGE_INDEX + 1 < WIZARD_FROM )); then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; fi
  stage "$1"
}

# store_secret NAME DESCRIPTION reads the secret's JSON on stdin and creates or updates it, tagged.
store_secret() {
  local name="$1" description="$2"
  if aws secretsmanager describe-secret --region "$AWS_REGION" --secret-id "$name" >/dev/null 2>&1; then
    aws secretsmanager put-secret-value --region "$AWS_REGION" --secret-id "$name" \
      --secret-string file:///dev/stdin >/dev/null
  else
    aws secretsmanager create-secret --region "$AWS_REGION" --name "$name" --description "$description" \
      --secret-string file:///dev/stdin >/dev/null
  fi
  # Cost allocation: the budget counts what is tagged project=birdjournal.
  aws secretsmanager tag-resource --region "$AWS_REGION" --secret-id "$name" --tags "${TAGS[@]}"
  printf '  %s✓ stored%s %s in AWS Secrets Manager (%s)\n' "$GREEN" "$RESET" "$name" "$AWS_REGION"
}

banner "BirdJournal: accounts backend (Apple, Google, AWS)"

if begin "Budget alarm: who gets the email"; then
  say "The stack's budget alarm emails at 80 % of the month's budget and at a 100 % forecast."
  say "The address stays in $ENV_FILE, out of the public repo."
  ask BUDGET_ALERT_EMAIL "Email for the budget alarm:"
  [[ "$BUDGET_ALERT_EMAIL" == *@* ]] || { warn "That isn't an email address."; exit 1; }
  write_env BUDGET_ALERT_EMAIL "$BUDGET_ALERT_EMAIL"
  note "The monthly limit is monthlyBudgetUsd in infra/cdk.json ($(jq -r '.context.monthlyBudgetUsd' "$INFRA_DIR/cdk.json") USD)."
  pause
fi

if begin "Apple: Sign in with Apple on the app's App ID"; then
  say "The Services ID (next stage) groups under the app's App ID, which needs the capability."
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Open the App ID $BUNDLE_ID."
  step "Capabilities → tick 'Sign In with Apple' (leave it 'Enable as a primary App ID') → Save → Confirm."
  note "Already ticked? Nothing to do."
  pause "Press Enter once Sign In with Apple is on for $BUNDLE_ID."
fi

if begin "Apple: the Services ID Cognito signs in as"; then
  open_url "https://developer.apple.com/account/resources/identifiers/add/serviceId"
  step "Description: BirdJournal sign-in. Identifier: $BUNDLE_ID.signin → Continue → Register."
  step "Open the new Services ID → tick 'Sign In with Apple' → Configure."
  step "Primary App ID: $BUNDLE_ID."
  step "Domains and Subdomains: $COGNITO_HOST"
  step "Return URLs: $IDP_RESPONSE"
  step "Next → Done → Continue → Save."
  ask APPLE_SERVICES_ID "Paste the Services ID identifier:"
  [[ -n "$APPLE_SERVICES_ID" ]] || { warn "No Services ID entered."; exit 1; }
  write_env APPLE_SERVICES_ID "$APPLE_SERVICES_ID"
fi

if begin "Apple: the Sign in with Apple key"; then
  open_url "https://developer.apple.com/account/resources/authkeys/add"
  step "Key Name: BirdJournal Sign in with Apple. Tick 'Sign in with Apple' → Configure."
  step "Primary App ID: $BUNDLE_ID → Save → Continue → Register."
  step "Download the .p8 file and note the Key ID on the same page."
  warn "Apple lets you download the key only once. Keep the .p8 out of the repo (e.g. ~/keys/)."
  ask APPLE_KEY_ID "Paste the Key ID (10 characters):"
  ask APPLE_KEY_PATH "Path to the downloaded .p8 file:"
  APPLE_KEY_PATH="${APPLE_KEY_PATH/#\~/$HOME}"
  [[ -f "$APPLE_KEY_PATH" ]] || { warn "No file at $APPLE_KEY_PATH."; exit 1; }
  grep -q "BEGIN PRIVATE KEY" "$APPLE_KEY_PATH" || warn "That file doesn't look like a .p8 private key."
  note "Your Team ID is under Membership details (top right of developer.apple.com/account)."
  open_url "https://developer.apple.com/account#MembershipDetailsCard"
  ask APPLE_TEAM_ID "Paste the Team ID (10 characters):"
  write_env APPLE_KEY_ID "$APPLE_KEY_ID"
  write_env APPLE_KEY_PATH "$APPLE_KEY_PATH"
  write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"
fi

if begin "AWS Secrets Manager: store Sign in with Apple"; then
  APPLE_SERVICES_ID="${APPLE_SERVICES_ID:-$(_existing APPLE_SERVICES_ID || true)}"
  APPLE_KEY_ID="${APPLE_KEY_ID:-$(_existing APPLE_KEY_ID || true)}"
  APPLE_KEY_PATH="${APPLE_KEY_PATH:-$(_existing APPLE_KEY_PATH || true)}"
  APPLE_TEAM_ID="${APPLE_TEAM_ID:-$(_existing APPLE_TEAM_ID || true)}"
  say "The stack reads $APPLE_SECRET at deploy time to configure Apple in Cognito."
  say "It lives outside the stack, so cdk destroy leaves it in place."
  note "Account $AWS_ACCOUNT · region $AWS_REGION · profile $AWS_PROFILE"
  note "Services ID $APPLE_SERVICES_ID · Team $APPLE_TEAM_ID · Key $APPLE_KEY_ID ($APPLE_KEY_PATH)"
  if confirm "Write $APPLE_SECRET now?"; then
    jq -n --arg services_id "$APPLE_SERVICES_ID" --arg team_id "$APPLE_TEAM_ID" --arg key_id "$APPLE_KEY_ID" \
      --rawfile private_key "$APPLE_KEY_PATH" \
      '{services_id: $services_id, team_id: $team_id, key_id: $key_id, private_key: $private_key}' \
      | store_secret "$APPLE_SECRET" "Sign in with Apple Services ID and key for the BirdJournal user pool"
  else
    SKIPPED+=("AWS secret $APPLE_SECRET: WIZARD_FROM=5 infra/scripts/accounts-wizard.sh")
  fi
  pause
fi

if begin "Google Auth Platform: register the app"; then
  say "Cognito signs birders in through Google, so Google needs to know the app exists."
  note "No Google Cloud project for BirdJournal yet? Create one first (name: birdjournal)."
  open_url "https://console.cloud.google.com/projectcreate"
  ask GOOGLE_CLOUD_PROJECT "Google Cloud project ID:"
  write_env GOOGLE_CLOUD_PROJECT "$GOOGLE_CLOUD_PROJECT"
  open_url "https://console.cloud.google.com/auth/overview?project=$GOOGLE_CLOUD_PROJECT"
  note "If Overview shows metrics instead of 'Get started', the app is registered: skip to Branding."
  step "Get started → App name 'Bird Journal', support email: yours → Next."
  step "Audience: External → Next. Contact information: yours → Next. Agree → Continue → Create."
  step "Branding → Authorized domains → Add domain → amazoncognito.com → Save."
  step "Audience → Publish app → Confirm. The app asks only for openid, email and profile,"
  step "which Google doesn't review, so any Google account can sign in."
  pause "Press Enter once amazoncognito.com is authorized and the app is in production."
fi

if begin "Google: create the web client"; then
  GOOGLE_CLOUD_PROJECT="${GOOGLE_CLOUD_PROJECT:-$(_existing GOOGLE_CLOUD_PROJECT || true)}"
  open_url "https://console.cloud.google.com/auth/clients?project=$GOOGLE_CLOUD_PROJECT"
  step "Create client → Application type: Web application. Name: BirdJournal Cognito."
  step "Authorized JavaScript origins → Add URI → https://$COGNITO_HOST"
  step "Authorized redirect URIs → Add URI → $IDP_RESPONSE"
  step "Create. A dialog shows the Client ID and the Client secret."
  warn "Google shows the client secret only in this dialog. Copy it before closing."
  note "Already closed it? Open the client, click 'Add secret', and use the new one."
  ask GOOGLE_OAUTH_CLIENT_ID "Paste the Client ID:"
  [[ "$GOOGLE_OAUTH_CLIENT_ID" == *.apps.googleusercontent.com ]] \
    || warn "That doesn't end in .apps.googleusercontent.com; check it's the Client ID."
  ask_secret GOOGLE_OAUTH_CLIENT_SECRET "Paste the Client secret (hidden):"
  [[ -n "$GOOGLE_OAUTH_CLIENT_SECRET" ]] || { warn "No Client secret entered, so nothing was saved."; exit 1; }
  write_env GOOGLE_OAUTH_CLIENT_ID "$GOOGLE_OAUTH_CLIENT_ID"
fi

if begin "AWS Secrets Manager: store the Google client"; then
  say "The stack reads $GOOGLE_SECRET at deploy time to configure Google in Cognito."
  if [[ -z "${GOOGLE_OAUTH_CLIENT_SECRET:-}" ]]; then
    warn "The client secret is only held for one run. Resume from stage 7 to enter it again."
    SKIPPED+=("AWS secret $GOOGLE_SECRET: WIZARD_FROM=7 infra/scripts/accounts-wizard.sh")
  elif confirm "Write $GOOGLE_SECRET now?"; then
    # Through env and stdin, so the client secret never shows up in a process list.
    CLIENT_ID="$GOOGLE_OAUTH_CLIENT_ID" CLIENT_SECRET="$GOOGLE_OAUTH_CLIENT_SECRET" \
      jq -n '{client_id: env.CLIENT_ID, client_secret: env.CLIENT_SECRET}' \
      | store_secret "$GOOGLE_SECRET" "Google OAuth web client for the BirdJournal user pool"
  else
    SKIPPED+=("AWS secret $GOOGLE_SECRET: WIZARD_FROM=7 infra/scripts/accounts-wizard.sh")
  fi
  pause
fi

if begin "CDK bootstrap (once per account and region)"; then
  say "CDK deploys through a CDKToolkit stack in $AWS_ACCOUNT / $AWS_REGION. This account is shared with"
  say "ivan-parallax, so an existing CDKToolkit is only checked, never bootstrapped over."
  bootstrap_status=0
  "$INFRA_DIR/scripts/check-bootstrap.sh" || bootstrap_status=$?
  case "$bootstrap_status" in
    0) note "Nothing to do." ;;
    2)
      if confirm "Bootstrap aws://$AWS_ACCOUNT/$AWS_REGION now?"; then
        (cd "$INFRA_DIR" && npm ci --silent && npx cdk bootstrap "aws://$AWS_ACCOUNT/$AWS_REGION")
      else
        SKIPPED+=("cdk bootstrap: cd infra && npx cdk bootstrap aws://$AWS_ACCOUNT/$AWS_REGION")
      fi ;;
    *)
      warn "Stopping: the shared bootstrap is too old. Ask the account's owner to upgrade it, then"
      warn "resume with WIZARD_FROM=9 infra/scripts/accounts-wizard.sh"
      exit 1 ;;
  esac
  pause
fi

if begin "Deploy the stack"; then
  say "infra/scripts/deploy.sh runs the template tests, deploys, and writes the stack's"
  say "sign-in settings into the app (BirdJournal/BirdJournal/Account/AccountServer.json)."
  if confirm "Deploy BirdJournal to $AWS_ACCOUNT / $AWS_REGION now?"; then
    "$INFRA_DIR/scripts/deploy.sh"
    note "Commit BirdJournal/BirdJournal/Account/AccountServer.json so the app can sign in."
  else
    SKIPPED+=("deploy: infra/scripts/deploy.sh")
  fi
  pause
fi

if begin "Billing: activate the project cost allocation tag"; then
  say "Cost Explorer and the budget filter on project=birdjournal only once 'project' is an"
  say "active cost allocation tag. A key shows up for activation up to 24 hours after the first"
  say "tagged resource exists, and activation is a payer-account setting: in an AWS Organization"
  say "the management account has to run it."
  status=$(aws ce list-cost-allocation-tags --region us-east-1 --tag-keys project \
    --query 'CostAllocationTags[0].Status' --output text 2>/dev/null || echo "error")
  case "$status" in
    Active) note "'project' is already active (ivan-parallax uses the same key): nothing to do." ;;
    Inactive)
      if confirm "Activate 'project' now?"; then
        if aws ce update-cost-allocation-tags-status --region us-east-1 \
          --cost-allocation-tags-status TagKey=project,Status=Active >/dev/null; then
          printf '  %s✓ activated%s project\n' "$GREEN" "$RESET"
        else
          warn "Refused: run it from the payer account, or Billing → Cost allocation tags → project → Activate."
          SKIPPED+=("cost allocation tag 'project' (payer account)")
        fi
      fi ;;
    None|"")
      warn "'project' isn't listed yet: tagged resources take up to 24 hours to appear."
      SKIPPED+=("cost allocation tag: WIZARD_FROM=11 infra/scripts/accounts-wizard.sh tomorrow") ;;
    *)
      warn "Couldn't read cost allocation tags (likely not the payer account)."
      note "From the payer account: aws ce update-cost-allocation-tags-status --region us-east-1 \\"
      note "  --cost-allocation-tags-status TagKey=project,Status=Active"
      open_url "https://us-east-1.console.aws.amazon.com/billing/home#/tags"
      SKIPPED+=("cost allocation tag 'project' (payer account)") ;;
  esac
  pause
fi

finish
note "check the deployed stack: cd infra && uv run python scripts/smoke.py   (or --provider Google)"
note "then on a device: Settings → Account → Sign in with Apple, and with Google"
printf '\n'
}

run_wizard "$@"; exit
